export type ImplementationBinding = Readonly<{
  architecture: 'in-process' | 'composed';
  status: 'implemented' | 'declared-limit';
  references: readonly string[];
  boundary: string;
}>;
export type ClaimSelector = Readonly<
  | { kind: 'runtime'; file: string; fullName: string }
  | { kind: 'compiler'; file: string; sentinel: string }
>;
export type ClaimLink = Readonly<{
  id: string;
  selectors: readonly ClaimSelector[];
  mutationSites: readonly string[];
  inProcessImplementation: ImplementationBinding;
  composedImplementation: ImplementationBinding;
}>;
export type ClaimSpan = Readonly<{ span: string; ids: readonly string[]; text: string }>;
const HEADING = '## Testbed evidence and scorecard contracts';
function invalid(): never { throw new Error('Claim evidence contract mismatch'); }
export const normalizeClaimWhitespace = (text: string): string => text.replace(/\s+/gu, ' ').trim();

/** The full section remains available independently of the marked span index. */
export function parseSchemaClaims(schema: string): { section: string; spans: ClaimSpan[]; ids: string[] } {
  const start = schema.indexOf(HEADING);
  if (start < 0 || schema.indexOf(HEADING, start + HEADING.length) >= 0) invalid();
  const tail = schema.slice(start);
  const end = tail.indexOf('\n## ', HEADING.length);
  const lines = (end < 0 ? tail : tail.slice(0, end)).split(/\r?\n/u);
  const section: string[] = [], spans: ClaimSpan[] = [];
  let active: { span: string; ids: string[]; lines: string[] } | undefined;
  let code = false;
  for (const line of lines) {
    const marker = line.match(/^\s*(\/\/|<!--) TV-CLAIM-SPAN:(s\d{3}) (BEGIN(?: TV-CLAIM:P-[A-Za-z0-9-]+)+|END)(?: -->)?\s*$/u);
    if (marker) {
      if ((marker[1] === '//') !== code || (marker[1] === '<!--' && !line.trimEnd().endsWith('-->'))) invalid();
      if (marker[3] === 'END') {
        if (!active || active.span !== marker[2] || normalizeClaimWhitespace(active.lines.join('\n')) === '') invalid();
        spans.push({ span: active.span, ids: active.ids, text: active.lines.join('\n') }); active = undefined;
      } else {
        if (active || spans.some((span) => span.span === marker[2])) invalid();
        const ids = [...marker[3].matchAll(/TV-CLAIM:(P-[A-Za-z0-9-]+)/gu)].map((match) => match[1]);
        if (new Set(ids).size !== ids.length) invalid();
        active = { span: marker[2], ids, lines: [] };
      }
      continue;
    }
    if (/^\s*<!-- TV-DEPLOYMENT-ASSUMPTION:(?:START|END) -->\s*$/u.test(line)) continue;
    if (line.includes('TV-CLAIM-SPAN:')) invalid();
    section.push(line);
    if (/^```(?:ts)?\s*$/u.test(line)) {
      if (active) invalid();
      code = !code;
    } else if (active) active.lines.push(line);
    else if (line.trim() && line !== HEADING) invalid();
  }
  if (active || code || spans.length === 0) invalid();
  return { section: section.join('\n'), spans, ids: [...new Set(spans.flatMap((span) => span.ids))].sort() };
}

function exactKeys(value: unknown, keys: string[]): asserts value is Record<string, unknown> {
  if (value === null || typeof value !== 'object' || Reflect.ownKeys(value).length !== keys.length
    || keys.some((key) => !Object.hasOwn(value, key)
      || !Object.hasOwn(Object.getOwnPropertyDescriptor(value, key)!, 'value'))) invalid();
}
function binding(value: unknown, architecture: ImplementationBinding['architecture']): void {
  exactKeys(value, ['architecture', 'status', 'references', 'boundary']);
  if (value.architecture !== architecture || !['implemented', 'declared-limit'].includes(String(value.status))
    || typeof value.boundary !== 'string' || value.boundary.trim().length === 0
    || !Array.isArray(value.references) || value.references.length === 0
    || value.references.some((ref) => typeof ref !== 'string' || !/^(?:src|testbed|scripts)\/[^:]+:[A-Za-z_$#][\w.$#-]*$/u.test(ref))) invalid();
}
export function validateClaimLinks(links: readonly ClaimLink[]): void {
  if (!links.length || new Set(links.map((row) => row.id)).size !== links.length) invalid();
  for (const row of links) {
    exactKeys(row, ['id', 'selectors', 'mutationSites', 'inProcessImplementation', 'composedImplementation']);
    if (!/^P-[A-Za-z0-9-]+$/u.test(row.id) || !Array.isArray(row.selectors) || !row.selectors.length
      || !Array.isArray(row.mutationSites) || !row.mutationSites.length
      || row.mutationSites.some((site) => typeof site !== 'string' || !site.includes(':'))) invalid();
    binding(row.inProcessImplementation, 'in-process'); binding(row.composedImplementation, 'composed');
    for (const selector of row.selectors) {
      exactKeys(selector, selector.kind === 'runtime' ? ['kind', 'file', 'fullName'] : ['kind', 'file', 'sentinel']);
      if ((selector.kind !== 'runtime' && selector.kind !== 'compiler') || typeof selector.file !== 'string'
        || !/^(?:src|testbed)\/.*\.test\.ts$/u.test(selector.file)
        || (selector.kind === 'runtime' ? typeof selector.fullName !== 'string' || !selector.fullName.trim()
          : typeof selector.sentinel !== 'string' || !selector.sentinel.trim())) invalid();
    }
  }
}

export type ExecutionAssertion = Readonly<{ file: string; fullName: string; status: string }>;
/** Acceptance callers supply current reports explicitly; default tests never read saved eval artifacts. */
export function validateClaimExecution(links: readonly ClaimLink[], assertions: readonly ExecutionAssertion[]): void {
  validateClaimLinks(links);
  for (const selector of links.flatMap((row) => row.selectors)) {
    if (selector.kind === 'compiler') continue;
    const matching = assertions.filter((item) => item.file === selector.file && item.fullName === selector.fullName);
    if (matching.length !== 1 || matching[0].status !== 'passed') invalid();
  }
}

/** Finite publishable-wording check. It does not certify arbitrary English. */
export function assertPublishableClaimWording(surfaces: readonly Readonly<{ name: string; text: string }>[]): void {
  if (!surfaces.length) invalid();
  for (const surface of surfaces) {
    const text = normalizeClaimWhitespace(surface.text).toLowerCase();
    if (/preflight\s+proves\s+docker\s+daemon\s+non-exposure/u.test(text)
      || /local\s+unix\s+endpoint\s+guarantees\s+the\s+docker\s+api\s+is\s+unreachable/u.test(text)
      || /successful\s+preflight\s+verifies\s+daemon\s+isolation/u.test(text)) {
      throw new Error('Publishable deployment claim overstates preflight');
    }
  }
}


const TABLE_HEADER = '| ID | selectors | mutationSites | inProcessImplementation | composedImplementation |';
/** Parse the closed table, while callers retain every prose line for the wording check. */
export function parseClaimTable(markdown: string): ClaimLink[] {
  const lines = markdown.split(/\r?\n/u);
  const headers = lines.flatMap((line, index) => line.trim() === TABLE_HEADER ? [index] : []);
  if (headers.length !== 1) invalid();
  const start = headers[0];
  if (!/^\|(?:\s*:?-{3,}:?\s*\|){5}$/u.test(lines[start + 1]?.trim() ?? '')) invalid();
  const rows: ClaimLink[] = [];
  const jsonCell = (cell: string): unknown => {
    if (!cell.startsWith('`') || !cell.endsWith('`') || cell.slice(1, -1).includes('`')) invalid();
    try { return JSON.parse(cell.slice(1, -1).replaceAll('&#124;', '|').replaceAll('&#96;', '`')); }
    catch { return invalid(); }
  };
  let end = start + 2;
  for (; end < lines.length && lines[end].trim().startsWith('|'); end++) {
    const cells = lines[end].trim().split('|');
    if (cells.length !== 7 || cells[0] !== '' || cells[6] !== '') invalid();
    const [id, selectors, mutationSites, inProcessImplementation, composedImplementation] = cells.slice(1, -1).map((cell) => cell.trim());
    rows.push({ id, selectors: jsonCell(selectors), mutationSites: jsonCell(mutationSites),
      inProcessImplementation: jsonCell(inProcessImplementation), composedImplementation: jsonCell(composedImplementation) } as ClaimLink);
  }
  // A displaced row after the table is still a linkage row, not harmless prose.
  if (lines.slice(0, start).concat(lines.slice(end)).some((line) => /^\s*\|\s*P-[A-Za-z0-9-]+\s*\|/u.test(line))) invalid();
  validateClaimLinks(rows);
  return rows;
}


